const { ApolloServer, gql } = require('@apollo/server');
const { expressMiddleware } = require('@apollo/server/express4');
const express = require('express');
const crypto = require('crypto');
const NodeCache = require('node-cache');

// Response cache with 5-minute TTL
const responseCache = new NodeCache({ stdTTL: 300, checkperiod: 60 });

const typeDefs = gql`
  type User {
    id: ID!
    email: String!
    role: String!
    apiKey: String
    internalNotes: String
  }

  type Query {
    me: User
    userProfile(id: ID!): User
  }
`;

// Cache key generation - uses operation name + variables but NOT auth context
function generateCacheKey(operationName, variables, extensions) {
  const keyData = JSON.stringify({
    op: operationName || '__anonymous',
    vars: variables || {},
    ext: extensions?.cacheHint || null
  });
  return crypto.createHash('md5').update(keyData).digest('hex');
}

const resolvers = {
  Query: {
    me: async (_, __, context) => {
      const cacheKey = generateCacheKey('me', {}, context.extensions);
      const cached = responseCache.get(cacheKey);
      if (cached) {
        return cached;
      }

      // Fetch user data based on authenticated context
      const userData = await fetchUserFromDB(context.user.id);
      const result = {
        id: userData.id,
        email: userData.email,
        role: userData.role,
        apiKey: userData.apiKey,
        internalNotes: userData.role === 'admin' ? userData.internalNotes : null
      };

      responseCache.set(cacheKey, result);
      return result;
    },
    userProfile: async (_, { id }, context) => {
      const cacheKey = generateCacheKey('userProfile', { id }, context.extensions);
      const cached = responseCache.get(cacheKey);
      if (cached) {
        return cached;
      }

      const userData = await fetchUserFromDB(id);
      const isOwner = context.user.id === id;
      const isAdmin = context.user.role === 'admin';

      const result = {
        id: userData.id,
        email: userData.email,
        role: userData.role,
        apiKey: (isOwner || isAdmin) ? userData.apiKey : null,
        internalNotes: isAdmin ? userData.internalNotes : null
      };

      responseCache.set(cacheKey, result);
      return result;
    }
  }
};

async function fetchUserFromDB(id) {
  // Simulated DB fetch
  return { id, email: `user${id}@corp.io`, role: 'admin', apiKey: 'sk_live_9x8w7v6u5t4s3r2q1p', internalNotes: 'Salary: $450k, SSN: 123-45-6789' };
}

function authenticateRequest(req) {
  const token = req.headers['authorization']?.replace('Bearer ', '');
  if (!token) throw new Error('Unauthorized');
  // Token validation against current rotation window
  const decoded = validateToken(token);
  return decoded;
}

function validateToken(token) {
  // JWT validation with current signing key
  const jwt = require('jsonwebtoken');
  return jwt.verify(token, process.env.JWT_SIGNING_KEY);
}

const app = express();

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
});

async function startServer() {
  await server.start();
  app.use('/graphql', express.json(), expressMiddleware(server, {
    context: async ({ req }) => {
      const user = authenticateRequest(req);
      return { user, extensions: req.body?.extensions };
    }
  }));
  app.listen(4000);
}

startServer();
